<template>
  <div v-draft="{ value: form, dirty: !!dirty }" class="content team-editor"><RouterLink to="/team-applications">← 返回球队报名</RouterLink><div class="team-page-heading"><div><span class="eyebrow">{{ data?.application.season_name }} · {{ data?.application.league_type }}</span><h1>{{ data?.application.team_name || '球队报名详情' }}</h1></div><button class="secondary" :disabled="busy || loading" @click="reloadDraft">重新载入（放弃未保存）</button></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="notice" role="status">{{ success }}</p>
    <template v-if="data"><section class="card"><div class="team-page-heading"><h2>{{ data.application.kind==='roster_change'?'名单变更 · ':'' }}{{ teamStatuses[data.application.status] }}</h2><span class="status">{{ data.permissions.can_manage ? '负责人／队长可操作' : '队员查看' }}</span></div><p>负责人：{{ data.manager.name }}{{ data.manager.student_id ? ' · '+data.manager.student_id : '' }}</p><p class="field-help">{{ data.application.kind==='roster_change'?'名单修改窗口':'报名窗口' }}（北京时间）：{{ time(data.window.opens_at) }} 至 {{ time(data.window.closes_at) }}</p><p v-if="data.window.rules_text" class="rules-text">{{ data.window.rules_text }}</p><p v-if="data.application.return_reason" class="notice">上次退回理由：{{ data.application.return_reason }}</p><p v-if="data.application.revoke_reason" class="notice">上次撤销通过原因：{{ data.application.revoke_reason }}</p><p v-if="data.application.registration_revoked && data.application.kind==='initial'" class="notice">报名通过已撤销，已有赛程和历史记录保留。{{ data.window.status==='open' ? '可在报名时间内修改原申请并重新提交，等待管理员审核。' : '当前不在报名时间内，暂不能修改或重新提交。' }}</p><p v-if="data.correction?.restricted" class="notice">报名已经截止，仅可替换管理员指定的球员。其他人员锁定；号码、角色、标记和球队资料按退回理由补正。</p><p v-if="data.application.status==='approved'" class="notice">此为已通过的申请记录。<RouterLink :to="'/teams/'+data.application.team_id">查看当前正式名单及申请中期变更 →</RouterLink></p></section>
      <TeamAutomaticReview :limits="data.window.limits" :result="data.auto_review" :current="data.current_auto_review"/>
      <section class="card"><h2>球队资料与名单</h2><fieldset :disabled="busy || !data.permissions.can_edit"><div class="team-fields"><label>球队名称<input v-model="form.team_name" maxlength="100"></label><label>上衣主要颜色<input v-model="form.shirt_color" maxlength="50" placeholder="例如：红"></label><label>裤子主要颜色<input v-model="form.shorts_color" maxlength="50" placeholder="例如：红"></label><label>袜子主要颜色<input v-model="form.socks_color" maxlength="50" placeholder="例如：红"></label></div></fieldset>
        <form v-if="data.permissions.can_edit && (!data.correction?.restricted || replacing!==null)" class="member-lookup" @submit.prevent="add"><label>{{ replacing===null ? '添加球员学号' : '替换为此学号球员' }}<input v-model="studentId" :disabled="busy" autocomplete="off"></label><button class="secondary" :disabled="busy || !studentId">{{ replacing===null ? '按学号添加' : '确认替换球员' }}</button><button v-if="replacing!==null" type="button" class="secondary" @click="replacing=null">取消替换</button></form>
        <p class="field-help">{{ data.permissions.can_edit ? '添加后先保存草稿，队员无需确认。号码可暂不填，提交前须完整；同队不得重复。首次报名指定队长保存后即可协作；正式球队变更队长须审核通过才更新权限。' : '名单按审核版本展示；学籍截图只对本人和管理员开放。' }}</p>
        <div class="team-counts"><span>名单 {{ form.members.length }} 人</span><span>外援 {{ form.members.filter(m=>m.is_foreign).length }} 人</span><span v-if="tagEnabled(data.window.limits,'sports_training')">运训 {{ form.members.filter(m=>m.is_sports_training).length }} 人</span><span v-if="tagEnabled(data.window.limits,'football_specialty')">足球特长生 {{ form.members.filter(m=>m.is_football_specialty).length }} 人</span><span>守门员 {{ form.members.filter(m=>m.is_goalkeeper).length }} 人</span></div>
        <p v-if="missingGender.length" class="error" role="alert">队伍中有人未选择性别，无法提交队伍创建申请：{{ missingGender.map(m=>m.name).join('、') }}。请队员登录补填后重新载入名单。</p><div class="member-cards"><article v-for="(m,index) in form.members" :key="m.key" class="member-card"><div class="member-heading"><div><h3>{{ m.name }}</h3><p>{{ m.gender==='male'?'男':m.gender==='female'?'女':'未选择性别' }}</p><p class="muted">{{ m.college }}{{ m.student_id ? ' · '+m.student_id : '' }}</p><span v-if="m.qualification_status" class="field-help">{{ qualifications[m.qualification_status] || '未注册学籍' }}{{ m.account_active===false ? ' · 账号已停用' : '' }}</span></div><button v-if="data.permissions.can_edit && !data.correction?.restricted" class="secondary" :disabled="busy" @click="form.members.splice(index,1)">移除{{ m.name }}</button><button v-if="data.permissions.can_edit && data.correction?.restricted && data.correction.replaceable_member_ids.includes(m.id)" class="secondary" :disabled="busy" @click="replacing=m.id;studentId=''">替换{{ m.name }}</button></div><p v-if="data.correction?.member_comments[m.id]" class="notice">管理员说明：{{ data.correction.member_comments[m.id] }}</p>
          <fieldset :disabled="busy || !data.permissions.can_edit" class="member-options"><label class="jersey">{{ m.name }}号码<input v-model="m.jersey_number" inputmode="numeric" maxlength="30" placeholder="待分配"></label><label class="check"><input type="radio" name="captain" :checked="m.is_captain" :aria-label="m.name+'任场上队长'" @change="setCaptain(index)">场上队长</label><label class="check"><input v-model="m.is_goalkeeper" type="checkbox" :aria-label="m.name+'守门员'">守门员</label><label class="check"><input v-model="m.is_foreign" type="checkbox" :aria-label="m.name+'外援'">外援</label><label v-if="tagEnabled(data.window.limits,'sports_training')" class="check"><input v-model="m.is_sports_training" type="checkbox" :aria-label="m.name+'运训'">运训</label><label v-if="tagEnabled(data.window.limits,'football_specialty')" class="check"><input v-model="m.is_football_specialty" type="checkbox" :aria-label="m.name+'足球特长生'">足球特长生</label><label>备注<input v-model="m.remark" maxlength="255"></label></fieldset>
        </article><p v-if="!form.members.length" class="empty">名单暂时为空，请按学号添加队员。</p></div>
        <div v-if="data.permissions.can_edit" class="team-actions"><button class="primary" :disabled="busy" @click="save">保存草稿</button><button class="secondary" :disabled="busy || dirty || missingGender.length>0" @click="preview=true">预览并提交</button><button v-if="data.permissions.can_submit_manual" class="secondary" :disabled="busy || dirty || missingGender.length>0" @click="submitManual">仍然提交申请（人工审核）</button><span v-if="dirty" class="field-help">先保存当前修改，再预览提交。</span></div><button v-if="data.permissions.can_withdraw" class="secondary" :disabled="busy" @click="withdraw">撤回整队申请</button>
      </section>
      <section v-if="preview" class="card submission-preview"><h2>整队提交预览</h2><p>{{ data.application.team_name }} · {{ data.application.league_type }}</p><p>球衣：{{ data.application.shirt_color || '/' }} / {{ data.application.shorts_color || '/' }} / {{ data.application.socks_color || '/' }}</p><ul><li v-for="m in data.members" :key="m.id">{{ m.jersey_number ?? '未分配号码' }}号 · {{ m.name }}{{ m.is_captain?' · 队长':'' }}{{ m.is_goalkeeper?' · 守门员':'' }}{{ m.is_foreign?' · 外援':'' }}{{ tagEnabled(data.window.limits,'sports_training')&&m.is_sports_training?' · 运训':'' }}{{ tagEnabled(data.window.limits,'football_specialty')&&m.is_football_specialty?' · 足球特长生':'' }}</li></ul><p class="field-help">提交时先检查必填资料及本赛事已配置的限制；不符合人数限制时保存原因，可选择仍然提交，交由管理员人工审核。</p><div class="team-actions"><button class="primary" :disabled="busy" @click="submit">确认提交整队审核</button><button class="secondary" :disabled="busy" @click="preview=false">返回修改</button></div></section>
      <section v-if="data.correction?.differences.length" class="card"><h2>与原名单或上次退回版本的差异</h2><ul><li v-for="(line,index) in data.correction.differences" :key="index">{{ line }}</li></ul></section>
      <TeamRolePanel v-if="data.application.status==='approved' && data.application.team_id && data.permissions.can_manage" :team-id="data.application.team_id" @refresh="load"/>
      <section v-if="data.events?.length" class="card"><details><summary>报名操作记录（最近100条）</summary><ol class="team-history"><li v-for="e in data.events" :key="e.id"><strong>{{ teamOperations[e.operation] }}</strong> · {{ time(e.created_at) }}<p v-if="e.reason">{{ e.reason }}</p><p v-for="(line,index) in e.changes||[]" :key="index">{{ line }}</p></li></ol></details></section>
    </template>
  </div>
</template>
<script setup>
import { ref, computed, watch } from 'vue'
import { confirmDraftLeave } from '../../../shared-ui/interaction.js'
import { useRoute, useRouter } from 'vue-router'
import { api, messageOf } from '../session'
import { teamStatuses, teamOperations, qualifications, time } from '../teamWorkflow'
import { tagEnabled } from '../../../shared-ui/teamRegistrationRules.js'
import TeamAutomaticReview from '../../../shared-ui/TeamAutomaticReview.vue'
import TeamRolePanel from '../components/TeamRolePanel.vue'
const route=useRoute(),router=useRouter(),data=ref(null),form=ref(null),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),studentId=ref(''),replacing=ref(null),preview=ref(false);let baseline='',rowKey=0,sequence=0
function payload(){return {team_name:form.value.team_name,shirt_color:form.value.shirt_color,shorts_color:form.value.shorts_color,socks_color:form.value.socks_color,members:form.value.members.map(m=>({id:m.id,player_id:m.player_id,jersey_number:m.jersey_number??'',remark:m.remark||null,is_captain:m.is_captain,is_goalkeeper:m.is_goalkeeper,is_foreign:m.is_foreign,is_sports_training:Boolean(m.is_sports_training),is_football_specialty:Boolean(m.is_football_specialty)}))}}
const missingGender=computed(()=>form.value?.members.filter(m=>!m.gender)||[])
const dirty=computed(()=>form.value&&JSON.stringify(payload())!==baseline)
function assign(value){if(value.access_changed){router.push('/team-applications');return}data.value=value;form.value={team_name:value.application.team_name,shirt_color:value.application.shirt_color||'',shorts_color:value.application.shorts_color||'',socks_color:value.application.socks_color||'',members:value.members.map(m=>({...m,key:++rowKey}))};baseline=JSON.stringify(payload());preview.value=false;replacing.value=null}
function reloadDraft(){if(confirmDraftLeave())load()}
async function load(){const n=++sequence;loading.value=true;error.value='';success.value='';try{const value=await api.get('/team-applications/'+route.params.id);if(n===sequence)assign(value)}catch(e){if(n===sequence){error.value=messageOf(e);if(e.response?.status===403)data.value=null}}finally{if(n===sequence)loading.value=false}}
function setCaptain(index){form.value.members.forEach((m,i)=>m.is_captain=i===index)}
async function add(){busy.value=true;error.value='';success.value='';try{const p=await api.get(`/team-applications/${route.params.id}/players`,{params:{student_id:studentId.value}});if(form.value.members.some(m=>m.player_id===p.id&&(replacing.value===null||m.id!==replacing.value))){error.value='该球员已经在名单中';return}if(replacing.value!==null){const m=form.value.members.find(m=>m.id===replacing.value);Object.assign(m,{player_id:p.id,name:p.name,student_id:p.student_id,college:p.college,gender:p.gender,qualification_status:'approved',account_active:true});replacing.value=null}else form.value.members.push({key:++rowKey,id:null,player_id:p.id,name:p.name,student_id:p.student_id,college:p.college,gender:p.gender,qualification_status:'approved',account_active:true,jersey_number:'',is_captain:false,is_goalkeeper:false,is_foreign:false,is_sports_training:false,is_football_specialty:false});studentId.value='';success.value='已添加到编辑名单，请保存草稿。'}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
async function action(work,message,checkAutomatic=false){busy.value=true;error.value='';success.value='';try{const value=await work();assign(value);if(checkAutomatic&&value.application.status==='auto_failed')error.value='自动审核失败，原因已保存。可按规则修改后重新提交，或选择仍然提交申请进行人工审核。';else success.value=message}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
const headers=()=>({headers:{'If-Match':String(data.value.application.revision)}})
const save=()=>action(()=>api.put('/team-applications/'+route.params.id,payload(),headers()),'草稿已保存。')
const submit=()=>action(()=>api.post(`/team-applications/${route.params.id}/submit`,{},headers()),'自动审核通过，整队申请已提交，等待管理员人工审核。',true)
const submitManual=()=>action(()=>api.post(`/team-applications/${route.params.id}/submit-manual`,{},headers()),'整队申请已提交人工审核，自动审核未通过的原因已保留。')
const withdraw=()=>window.confirm('确认撤回整队申请？当前正式名单不会改变。') && action(()=>api.post(`/team-applications/${route.params.id}/withdraw`,{},headers()),'申请已撤回。名单变更不影响当前正式名单，可在开放窗口内修改重提。')
watch(()=>route.params.id,load,{immediate:true})
</script>
